def register_exception_handlers(fast_app: FastAPI) -> None:
    """
    注册全局异常处理器

    Args:
        fast_app: FastAPI应用实例
    """

    @fast_app.exception_handler(Exception)
    async def global_exception_handler(request: Request, exc: Exception):
        """全局异常处理"""
        try:
            logger.error(f"全局异常捕获 | path={request.url.path} | method={request.method} | error={type(exc).__name__}: {exc!s}", exc_info=True)
            return JSONResponse(status_code=500, content={"code": 500, "message": "服务器内部错误", "data": None})
        except Exception as e:
            logger.critical(f"全局异常处理器失败: {e}")
            return JSONResponse(status_code=500, content={"code": 500, "message": "服务器严重错误", "data": None})

