def replace_wxwork_emoji(text: str) -> str:
    """将企微表情占位符替换为 emoji，未匹配的 [xxx] 直接删除"""
    if not text:
        return text
    for placeholder, emoji in _EMOJI_MAP.items():
        text = text.replace(placeholder, emoji)
    # 未匹配的 [xxx] 格式一律删除
    text = re.sub(r"\[[^\]]{1,10}\]", "", text)
    return text.strip()

