class ConfigObject:
    """
    将字典转换为可通过点号语法访问的对象

    Example:
        >>> data = {"server": {"host": "localhost", "port": 8000}}
        >>> config = ConfigObject(data)
        >>> print(config.server)  # "localhost"
        >>> print(config.server)  # 8000
    """

    def __init__(self, data: dict):
        for key, value in data.items():
            if isinstance(value, dict):
                # 嵌套字典递归转换为 ConfigObject
                setattr(self, key, ConfigObject(value))
            elif isinstance(value, list):
                # 列表中的字典也转换
                setattr(self, key, [ConfigObject(item) if isinstance(item, dict) else item for item in value])
            else:
                setattr(self, key, value)

    def __getattr__(self, name):
        """访问不存在的配置项时返回空配置对象，支持链式访问"""
        return None

    def __repr__(self):
        attrs = {k: v for k, v in self.__dict__.items()}
        return f"ConfigObject({attrs})"

