class TaskManager(ABC):
    @abstractmethod
    async def on_get_task(self, request: GetTaskRequest) -> GetTaskResponse:
        """获取任务的详细信息，需要检索特定任务的信息时调用这个方法，主要用于查看任务的当前状态、参数和历史记录。"""
        pass

    @abstractmethod
    async def on_cancel_task(self, request: CancelTaskRequest) -> CancelTaskResponse:
        """取消一个正在进行的任务，用户请求取消一个任务时调用这个方法，需要检查任务是否可以被取消，并执行取消操作。"""
        pass

    @abstractmethod
    async def on_send_task(self, request: SendTaskRequest) -> SendTaskResponse:
        """发送一个新的任务，用户请求创建并执行一个新任务时调用这个方法，需要处理任务的初始化和调度。"""
        pass

    @abstractmethod
    async def on_send_task_subscribe(
        self, request: SendTaskStreamingRequest
    ) -> Union[AsyncIterable[SendTaskStreamingResponse], JSONRPCResponse]:
        """订阅一个任务的更新，用户希望接收某个任务的状态更新时调用这个方法，用于实时通知任务的进展。"""
        pass

    @abstractmethod
    async def on_set_task_push_notification(
        self, request: SetTaskPushNotificationRequest
    ) -> SetTaskPushNotificationResponse:
        """设置任务的推送通知，用户希望为任务配置推送通知时调用这个方法，需要存储通知的配置以便在任务状态变化时发送通知。"""
        pass

    @abstractmethod
    async def on_get_task_push_notification(
        self, request: GetTaskPushNotificationRequest
    ) -> GetTaskPushNotificationResponse:
        """获取任务的推送通知配置，用户请求查看任务的推送通知设置时调用这个方法，返回当前的通知配置。"""
        pass

    @abstractmethod
    async def on_resubscribe_to_task(
        self, request: TaskResubscriptionRequest
    ) -> Union[AsyncIterable[SendTaskResponse], JSONRPCResponse]:
        """重新订阅一个任务的更新，用户希望重新接收某个任务的状态更新时调用这个方法，用于恢复之前的订阅。"""
        pass

