class StageStatusContent(BaseContent):
    """
    阶段状态消息

    用于推送阶段的开始/完成/失败状态

    示例输出：
    {
      "stage": "reason",
      "content": {
        "status": "UPDATING",
        "title": "正在思考中"
      }
    }

    当 title 为 None 时，不输出该字段
    """

    status: MessageStatus = Field(..., description="阶段状态")
    title: str | None = Field(default=None, description="阶段标题")

    @model_serializer
    def serialize_model(self):
        """过滤 None 值字段"""
        result = {"status": self.status.value}
        if self.title is not None:
            result["title"] = self.title
        return result

