class CardTitleContent(BaseContent):
    """
    卡片标题消息

    用于推送卡片的标题和状态

    示例输出（REASON 阶段）：
    {
      "stage": "reason",
      "content": {
        "reason": {
          "reasonId": "xxx",
          "title": "正在分析问题...",
          "status": "UPDATING"
        }
      }
    }

    示例输出（MESSAGE 阶段）：
    {
      "stage": "message",
      "content": {
        "message": {
          "messageId": "xxx",
          "title": "回答完成",
          "status": "DONE"
        }
      }
    }
    """

    card_id: str = Field(..., description="卡片容器ID")
    title: str = Field(..., description="卡片标题")
    status: MessageStatus = Field(..., description="卡片状态")
    stage: MessageStage = Field(..., description="消息阶段", exclude=True)  # 不序列化，仅用于逻辑判断

    @model_serializer
    def serialize_model(self):
        """根据 stage 动态生成字段名"""
        # REASON -> reasonId, MESSAGE -> messageId
        id_field = "reasonId" if self.stage == MessageStage.REASON else "messageId"
        return {id_field: self.card_id, "title": self.title, "status": self.status.value}

