class CardDataContent(BaseContent):
    """
    卡片数据消息

    用于推送卡片的数据内容（包含卡片实体）

    示例输出（REASON 阶段）：
    {
      "stage": "reason",
      "content": {
        "reason": {
          "reasonId": "xxx",
          "content": {
            "id": "yyy",
            "type": "textCard",
            "status": "UPDATING",
            "content": "卡片内容"
          }
        }
      }
    }

    示例输出（MESSAGE 阶段）：
    {
      "stage": "message",
      "content": {
        "message": {
          "content": {
            "id": "yyy",
            "type": "plainTextCard",
            "status": "UPDATING",
            "content": "消息内容"
          }
        }
      }
    }

    注意：MESSAGE 阶段没有 messageId 字段，直接是 content
    """

    card_id: str = Field(..., description="卡片容器ID")
    content: BaseCardModel = Field(..., description="卡片实体")
    stage: MessageStage = Field(..., description="消息阶段", exclude=True)  # 不序列化，仅用于逻辑判断

    @model_serializer
    def serialize_model(self):
        """
        自定义序列化：根据 stage 动态生成结构

        关键修复：
        手动调用 content.model_dump() 确保触发 BaseCardModel 的 @model_serializer
        """
        content_data = self.content.model_dump()

        # REASON 阶段：包含 reasonId
        if self.stage == MessageStage.REASON:
            return {"reasonId": self.card_id, "content": content_data}
        # MESSAGE 阶段：不包含 messageId，直接是 content
        else:
            return {"content": content_data}

