class ProtocolWrapper(BaseModel):
    """
    协议包装器

    根据消息类型自动选择包装方式：
    1. StageStatusContent: 直接输出 {status: ..., title: ...}
    2. CardTitleContent/CardDataContent: 包装为 {reason: {...}} 或 {message: {...}}

    使用示例：
        # 阶段状态消息
        content = StageStatusContent(status=MessageStatus.UPDATING, title="正在思考")
        wrapper = ProtocolWrapper(stage=MessageStage.REASON, content=content)
        # 序列化后：{status: "UPDATING", title: "正在思考"}

        # 卡片标题消息
        content = CardTitleContent(reason_id="xxx", title="分析中", status=UPDATING)
        wrapper = ProtocolWrapper(stage=MessageStage.REASON, content=content)
        # 序列化后：{reason: {reasonId: "xxx", title: "分析中", status: "UPDATING"}}
    """

    stage: MessageStage
    content: StageContent

    @model_serializer
    def serialize_model(self):
        """
        自定义序列化

        输出格式：
        1. StageStatusContent: 直接返回内容
           输出: {status: ..., title: ...}

        2. CardTitleContent/CardDataContent: 包装为 {reason: ...} 或 {message: ...}
           输出: {reason: {reasonId: ..., ...}} 或 {message: {...}}

        注意：不使用 exclude_none=True，因为：
        1. BaseCardModel 有自己的 @model_serializer 处理 None 过滤
        2. 父对象的 exclude_none=True 会阻止子对象的 @model_serializer 执行
        """
        # 序列化内容对象（使用 by_alias，但不使用 exclude_none）
        content_dict = self.content.model_dump(by_alias=True)
        # 阶段状态消息：直接返回内容
        if isinstance(self.content, StageStatusContent):
            return content_dict
        # 卡片消息：包装为 {reason: ...} 或 {message: ...}
        stage_key = self.stage.value  # "reason" 或 "message"
        return {stage_key: content_dict}

