class TextCard(BaseCardModel):
    """
    富文本卡片（用于 REASON 阶段）

    字段说明：
    - content: 富文本内容（支持 Markdown 等格式化）
    """

    content: str | None = Field(default=None, description="富文本内容")

    def get_delta_content(self) -> str | None:
        """返回 content 字段内容"""
        return self.content

    def append_delta_content(self, delta: str) -> None:
        """追加到 content 字段"""
        if self.content is None:
            self.content = delta
        else:
            self.content += delta

