class PlainTextCard(BaseCardModel):
    """
    纯文本卡片（用于 MESSAGE 阶段）

    字段说明：
    - content: 纯文本内容（无格式化）
    """

    content: PlanTextCardContent = Field(default=None, description="纯文本内容")

    def get_delta_content(self) -> str | None:
        """返回 content.text 字段内容"""
        if self.content is None:
            return None
        return self.content.text

    def append_delta_content(self, delta: str) -> None:
        """追加到 content.text 字段"""
        if self.content is None:
            self.content = PlanTextCardContent(text=delta)
        else:
            if self.content.text is None:
                self.content.text = delta
            else:
                self.content.text += delta

