def _story_summary(story_content: dict) -> str:
    """将故事内容提炼为一段给模型理解的叙述文字"""
    title = story_content.get("cover_title") or ""
    cause_ctx = _safe_get("context", story_content, "cause")
    cause_quote = _safe_get("customer_quote", story_content, "cause")
    tl_text = _timeline_text(story_content.get("process") or {})
    result_quote = _safe_get("customer_quote", story_content, "result")

    parts = [f"故事标题：{title}"] if title else []
    if cause_ctx:
        parts.append(f"起因：{cause_ctx}")
    if cause_quote:
        parts.append(f'业主诉求原话："{cause_quote}"')
    if tl_text:
        parts.append(f"服务过程：{tl_text}")
    if result_quote:
        parts.append(f'业主感谢原话："{result_quote}"')
    return "\n".join(parts)

