core/poster/step1_scene_gen.py::_decode_.source_code:
def _decode_image_url(url: str) -> bytes | None:
    if url.startswith("data:"):
        return base64.b64decode(url.split(",", 1)[1])
    # 远程 URL，同步下载（调用方在 async 中，需要 ensure_future 处理）
    import urllib.request
    return urllib.request.urlopen(url, timeout=30).read()

def _decode_text_image(text: str) -> bytes | None:
    m = re.search(r"<inline>\s*<data>([\s\S]+?)</data>", text)
    if m:
        return base64.b64decode(m.group(1).strip())
    if text.strip().startswith("data:"):
        return base64.b64decode(text.strip().split(",", 1)[1])
    return None

