def _role_only(role_str: str) -> str:
    _ROLE_TITLES = ["交付专家", "项目经理", "全案设计师", "设计师", "工长", "监理",
                    "工程师", "主任", "专员", "顾问", "管家", "经营部经理",
                    "售后", "客服", "施工经理", "安装师傅"]
    if not role_str:
        return ""
    if "业主" in role_str:
        return "业主"
    if "服务者" in role_str:
