def _normalize_timeline(data: Any) -> list[dict]:
    """将原始的 timeline 数据（可能是 list/dict/str）统一为 list[dict]"""
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        return [data]
    if isinstance(data, str):
        items = []
        for line in data.strip().split("\n"):
            parts = line.split("|", 2)
            if len(parts) == 3:
                items.append({"time": parts[0], "role": parts[1], "action": parts[2]})
        return items
    return []

