def ensure_dict(value: Any, default: dict[str, Any] | None = None) -> dict[str, Any]:
    """
    确保返回字典类型

    Args:
        value: 任意值
        default: 默认字典

    Returns:
        字典对象

    Examples:
        >>> ensure_dict(None)
        {}
        >>> ensure_dict("not a dict")
        {}
        >>> ensure_dict({'a': 1})
        {'a': 1}
    """
    if isinstance(value, dict):
        return value
    return default or {}

utils/time_utils.py::TimeUtils.source_code:
class TimeUtils:
    """时间转换工具类"""

    @staticmethod
    def datetime_to_timestamp(dt: datetime | str | None) -> int:
        """
        将datetime转换为时间戳

        Args:
            dt: datetime对象、时间字符串或None

        Returns:
            int: 时间戳（秒级）
        """
        if dt is None:
            return 0

        if isinstance(dt, str):
            try:
                dt = datetime.fromisoformat(dt.replace("Z", "+00:00"))
            except ValueError:
                return 0

        if isinstance(dt, datetime):
            return int(dt.timestamp())

        return 0

    @staticmethod
    def timestamp_to_datetime(timestamp: int | str | None) -> datetime:
        """
        将时间戳转换为datetime

        Args:
            timestamp: 时间戳（秒级）或字符串

        Returns:
            datetime: datetime对象
        """
        if timestamp is None or timestamp == 0:
            return datetime(1970, 1, 1, 8, 0, 1)

        if isinstance(timestamp, str):
            try:
                timestamp = int(timestamp)
            except ValueError:
                return datetime(1970, 1, 1, 8, 0, 1)

        try:
            return datetime.fromtimestamp(timestamp)
        except (ValueError, OSError):
            return datetime(1970, 1, 1, 8, 0, 1)

    @staticmethod
    def datetime_to_string(dt: datetime | None, fmt: str = "%Y-%m-%d %H:%M:%S") -> str:
        """
        将datetime转换为字符串

        Args:
            dt: datetime对象
            fmt: 格式化字符串

        Returns:
            str: 时间字符串
        """
        if dt is None:
            return ""

        try:
            return dt.strftime(fmt)
        except (ValueError, AttributeError):
            return ""

    @staticmethod
    def string_to_datetime(time_str: str | None, fmt: str = "%Y-%m-%d %H:%M:%S") -> datetime:
        """
        将字符串转换为datetime

        Args:
            time_str: 时间字符串
            fmt: 格式化字符串

        Returns:
            datetime: datetime对象
        """
        if not time_str:
            return datetime(1970, 1, 1, 8, 0, 1)

        try:
            return datetime.strptime(time_str, fmt)
        except ValueError:
            # 尝试ISO格式
            try:
                return datetime.fromisoformat(time_str.replace("Z", "+00:00"))
            except ValueError:
                return datetime(1970, 1, 1, 8, 0, 1)

    @staticmethod
    def now_timestamp() -> int:
        """
        获取当前时间戳

        Returns:
            int: 当前时间戳（秒级）
        """
        return int(datetime.now().timestamp())

    @staticmethod
    def now_string(fmt: str = "%Y-%m-%d %H:%M:%S") -> str:
        """
        获取当前时间字符串

        Args:
            fmt: 格式化字符串

        Returns:
            str: 当前时间字符串
        """
        return datetime.now().strftime(fmt)

    @staticmethod
    def days_ago_timestamp(days: int) -> int:
        """
        获取N天前的时间戳

        Args:
            days: 天数

        Returns:
            int: N天前的时间戳
        """
        from datetime import timedelta

        past_date = datetime.now() - timedelta(days=days)
        return int(past_date.timestamp())

    @staticmethod
    def days_since_timestamp(timestamp: int) -> int:
        """
        计算时间戳距离现在的天数

        Args:
            timestamp: 时间戳（秒级）

        Returns:
            int: 天数差
        """
        if timestamp <= 0:
            return 999999  # 无效时间戳返回一个很大的值

        current_timestamp = int(datetime.now().timestamp())
        return (current_timestamp - timestamp) // (24 * 60 * 60)

    @staticmethod
    def standard_time_to_timestamp(time_str: str | None) -> int:
        """
        将标准时间格式字符串转换为秒级时间戳
        专门处理 "YYYY-MM-DD HH:MM:SS" 格式

        Args:
            time_str: 时间字符串，格式为 "2025-09-17 02:33:26"

        Returns:
            int: 秒级时间戳，如果格式错误返回 0

        Examples:
            >>> TimeUtils.standard_time_to_timestamp("2025-09-17 02:33:26")
            1726522406
            >>> TimeUtils.standard_time_to_timestamp("invalid")
            0
        """
        if not time_str:
            return 0

        try:
            dt = datetime.strptime(time_str, "%Y-%m-%d %H:%M:%S")
            return int(dt.timestamp())
        except ValueError:
            return 0

    @staticmethod
    def iso_to_standard_format(iso_time_str: str | None) -> str:
        """
        将 ISO 时间格式转换为标准时间格式
        从 "2025-09-17T10:55:12.000+00:00" 转换为 "2025-09-17 10:55:12"

        Args:
            iso_time_str: ISO 格式时间字符串

        Returns:
            str: 标准格式时间字符串 "YYYY-MM-DD HH:MM:SS"，如果格式错误返回空字符串

        Examples:
            >>> TimeUtils.iso_to_standard_format("2025-09-17T10:55:12.000+00:00")
            "2025-09-17 10:55:12"
            >>> TimeUtils.iso_to_standard_format("invalid")
            ""
        """
        if not iso_time_str:
            return ""

        try:
            # 使用 string_to_datetime 方法解析 ISO 格式
            dt = TimeUtils.string_to_datetime(iso_time_str)
            # 转换为标准格式字符串
            return TimeUtils.datetime_to_string(dt, "%Y-%m-%d %H:%M:%S")
        except Exception:
            return ""

    @staticmethod
    def format_entrust_time(time_str: str, fmt="%m-%d %H:%M") -> str:
        """
        将委托时间格式化为 MM-dd HH:mm 格式
        从 "2025-09-18 15:59:43" 转换为 "09-18 15:59"

        Args:
            time_str: 时间字符串，格式为 "YYYY-MM-DD HH:MM:SS"
            fmt: 输出格式，默认 "%m-%d %H:%M"

        Returns:
            str: 格式化后的时间字符串 "MM-dd HH:mm"，如果格式错误返回空字符串

        Examples:
            >>> TimeUtils.format_entrust_time("2025-09-18 15:59:43")
            "09-18 15:59"
            >>> TimeUtils.format_entrust_time("invalid")
            ""
            >>> TimeUtils.format_entrust_time(None)
            ""
        """
        if not time_str:
            return ""
        dt = TimeUtils.string_to_datetime(time_str)
        return TimeUtils.datetime_to_string(dt, fmt)

    @staticmethod
    def format_date_only(time_str: str | None) -> str:
        """
        将时间格式化为只包含年月日
        从 "2025-10-09 14:46:49" 转换为 "2025-10-09"

        Args:
            time_str: 时间字符串，格式为 "YYYY-MM-DD HH:MM:SS"

        Returns:
            str: 格式化后的日期字符串 "YYYY-MM-DD"，如果格式错误返回空字符串

        Examples:
            >>> TimeUtils.format_date_only("2025-10-09 14:46:49")
            "2025-10-09"
            >>> TimeUtils.format_date_only("invalid")
            ""
            >>> TimeUtils.format_date_only(None)
            ""
        """
        if not time_str:
            return ""
        dt = TimeUtils.string_to_datetime(time_str)
        return TimeUtils.datetime_to_string(dt, "%Y-%m-%d")

