async def _get_order_code(chat_id: str) -> str | None:
    """根据群 ID 查订单号，取第一条 bindStatus=1 的记录"""
    try:
        client = await AsyncHttpClientManager.get_client()
        resp = await client.get(
            f"{_SCRM_HOST}/api/group/binding-info",
            params={"chatId": chat_id, "bizCode": "", "bizId": ""},
        )
        items = resp.json().get("data") or []
        logger.info(f"[StoryGraph] SCRM binding chat_id={chat_id} candidates={len(items)}")
        for item in items:
            if item.get("bindStatus") == 1 and item.get("entityCode"):
                return item["entityCode"]
    except Exception as e:
        logger.warning(f"[SCRM] 查订单号失败 chat_id={chat_id}: {e}")
    return None

def _extract_text(raw: str) -> str:
    raw = str(raw).strip()
    if raw.startswith("{"):
        try:
            obj = json.loads(raw)
            return str(obj.get("content") or obj.get("description") or obj.get("title") or "").strip()
        except Exception:
            pass
    return raw

def _normalize_prefilter_text(text: str) -> str:
    text = replace_wxwork_emoji(str(text or "")).strip()
    text = re.sub(r"@所有人", "", text)
    text = re.sub(r"\s+", "", text)
    return text.strip("，。！？!,.、；;：:")

def _prefilter_skip_reason(text: str) -> str:
    normalized = _normalize_prefilter_text(text)
    snippet = repr((text or "")[:60])
    if not normalized or normalized in _INVALID_EXACT_TEXTS or len(normalized) <= 2:
        return f"无效或过短消息: {snippet}"
    if any(marker in normalized for marker in _INVALID_MARKERS):
        return f"无效或过短消息: {snippet}"
    if _matches_any(normalized, _RISK_PATTERNS):
        return f"命中高风险内容: {snippet}"
    if _matches_any(normalized, _UNFINISHED_PATTERNS):
        return f"只有后续期望，未形成结果: {snippet}"

    has_positive = _contains_any(normalized, _POSITIVE_WORDS)
    has_action = _contains_any(normalized, _SERVICE_ACTION_WORDS)
    has_result = _contains_any(normalized, _RESULT_WORDS)
    if not has_positive:
        return f"缺少正向夸夸信号: {snippet}"
    if not (has_action or has_result):
        return f"缺少服务动作或完成结果: {snippet}"
    return ""

def _owner_label_from_name(name: str | None, gender: str | None) -> str:
    name = str(name or "").strip()
    if not name or not re.match(r"^[\u4e00-\u9fa5]", name):
        return ""
    if gender == "female":
        return f"{name[0]}女士"
    if gender == "male":
        return f"{name[0]}先生"
    return ""

def _build_identity_hints(
    order_customer_name: str | None = None,
    order_customer_gender: str | None = None,
) -> dict[str, str]:
    order_customer_label = _owner_label_from_name(order_customer_name, order_customer_gender)
    return {
        "order_customer_name": order_customer_name or "",
        "order_customer_gender": order_customer_gender or "",
        "order_customer_label": order_customer_label,
    }

def _parse_message_time(value: Any) -> datetime | None:
    if not isinstance(value, (int, float)):
        return None
    ts = value / 1000 if value > 1e12 else value
    try:
        return datetime.fromtimestamp(ts)
    except OSError:
        return None

def _find_praise_by_msg_id(items: list[dict], msg_id: str) -> str:
    if not msg_id:
        return ""
    for item in items:
        if str(item.get("msgId") or "") == msg_id:
            content = str(item.get("message") or "").strip()
            if content:
                return content
    return ""

def _should_keep(item: dict, praise_msg_id: str) -> bool:
    is_praise = praise_msg_id and str(item.get("msgId") or "") == praise_msg_id
    if is_praise:
        return bool(str(item.get("message") or "").strip())
    if item.get("role") == 50000000:
        return False
    if item.get("msgType") != 1:
        return False
    return bool(str(item.get("message") or "").strip())

def _convert_scrm_context_messages(items: list[dict], request: Any, praise_msg_id: str = "") -> list[WxworkMessage]:
    messages: list[WxworkMessage] = []
    for item in items:
        if not _should_keep(item, praise_msg_id):
            continue
        send_time = _parse_message_time(item.get("msgTime"))
        if send_time is None:
            continue
        messages.append(WxworkMessage(
            group_id=request.group_id,
            sender=str(item.get("senderNick") or "").strip(),
            sender_role=str(item.get("roleName") or "").strip(),
            send_time=send_time,
            content=str(item.get("message") or "").strip(),
        ))
    return messages

def _get_story_owner_value(story: StoryContent, field: str, default: Any = "") -> Any:
    owner = getattr(story, "story_owner", None)
    if owner is None:
        return default
    if isinstance(owner, dict):
        return owner.get(field, default)
    return getattr(owner, field, default)

def _resolve_poster_owner(story: StoryContent, order_customer_name: str | None, order_customer_gender: str | None) -> tuple[str, str]:
    display_name = str(_get_story_owner_value(story, "display_name", "") or "").strip()
    story_gender = str(_get_story_owner_value(story, "gender", "") or "").strip().lower()

    if display_name:
        owner_name = display_name
    else:
        owner_name = (order_customer_name or "").strip() or "业主"

    if story_gender in ("male", "female"):
        owner_gender = story_gender
    else:
        owner_gender = order_customer_gender or "male"

    return owner_name, owner_gender

async def _preprocess_node(state: StoryPipelineState) -> dict:
    """拼消息文本、提取参与人、更新 task 状态"""
    task_id = state["task_id"]
    await StoryTaskCRUD.update_by_id(task_id, {"status": "PROCESSING", "pipeline_stage": "preprocess"})
    messages = state.get("context_messages") or []

    clean_messages = [
        f"[{m.send_time}][{m.sender_role}]{m.sender}: {text}"
        for m in messages
        if (text := _extract_text(m.content).strip())
    ]
    messages_text = "\n".join(clean_messages)
    participants = list({
        f"{m.sender_role}{m.sender}"
        for m in messages
        if m.sender_role and "业主" not in m.sender_role
    })

    await StoryTaskCRUD.update_by_id(task_id, {
        "message_count": len(messages),
    })
    logger.info(
        f"[StoryGraph] task_id={task_id} preprocess done "
        f"input_messages={len(messages)} clean_messages={len(clean_messages)} "
        f"participants={len(participants)} text_chars={len(messages_text)}"
    )
    return {"clean_text": replace_wxwork_emoji(messages_text), "participants": participants}

def _owner_fields(story: StoryContent) -> dict:
    return {
        "story_owner_raw_name": _sv(story, "raw_name"),
        "story_owner_display_name": _sv(story, "display_name") or "业主",
        "story_owner_gender": _sv(story, "gender") or "unknown",
        "story_owner_source": _sv(story, "source"),
        "story_owner_confidence": str(_sv(story, "confidence") or 0.0),
        "story_owner_reason": _sv(story, "reason"),
    }

def _tl_json(process) -> str | None:
    if not process or not process.timeline:
        return None
    return json.dumps(
        [{"time": t.time, "role": t.role, "action": t.action, "timeline_highlight": t.timeline_highlight}
         for t in process.timeline],
        ensure_ascii=False,
    )

def _apply_poster_fields(output_fields: dict, state: dict) -> None:
    poster_url = state.get("poster_url")
    poster_template = state.get("poster_template")
    if not poster_url and not poster_template:
        return
    output_fields["image_model"] = "gemini-2.0-flash-preview-image-generation"
    output_fields["owner_gender"] = state.get("poster_owner_gender") or state.get("order_customer_gender")
    if poster_url:
        output_fields["poster_url"] = poster_url
    if poster_template:
        output_fields["poster_template"] = poster_template
        output_fields["poster_style"] = _TPL_STYLE.get(poster_template, "")
    for key in ("poster_width", "poster_height"):
        if state.get(key):
            output_fields[key] = state.get(key)

def _route_after_write(state: StoryPipelineState) -> str:
    story = state.get("story")
    if story is None or story.story_level == "C":
        return "mark_skipped"
    if story.story_level in ("A", "S"):
        return "gen_poster"
    return "persist"

def _get_compiled() -> CompiledStateGraph:
    global _compiled
    if _compiled is None:
        _compiled = build_story_graph().compile()
    return _compiled

async def run_story_pipeline(task_id: int, request: Any) -> None:
    """执行故事分析流水线（异常统一在此捕获，置 task FAILED）"""
    try:
        logger.info(f"[StoryGraph] task_id={task_id} pipeline start group_id={request.group_id} praise_time={request.praise_time}")
        await _get_compiled().ainvoke({"task_id": task_id, "request": request})
        logger.info(f"[StoryGraph] task_id={task_id} pipeline end")
    except Exception as e:
        logger.error("[StoryGraph] task_id={} 失败: {}", task_id, e, exc_info=True)
        await StoryTaskCRUD.update_by_id(task_id, {
            "completed_at": datetime.now(),
            "status": "FAILED",
            "error_msg": str(e)[:2000],
        })

