class AuthMiddleware(BaseHTTPMiddleware):
    """
    认证中间件

    功能：
    1. 从 Authorization Header 或 Query 参数中提取 Token
    2. 调用 session_client.verify_token() 验证 Token
    3. 将 ucid 注入到 Request Headers 中（X-Nrs-User-Id）
    4. Token 验证失败返回 401

    跳过路径：
    - 从配置文件 config.auth.skip_paths 读取
    """

    def __init__(self, app):
        """初始化中间件"""
        super().__init__(app)
        # 从配置文件读取无需认证的路径列表
        self.skip_paths = set(config.auth.skip_paths)

    async def dispatch(self, request: Request, call_next) -> Response:
        """
        处理请求

        Args:
            request: HTTP 请求
            call_next: 下一个中间件/处理器

        Returns:
            HTTP 响应
        """
        # 1. OPTIONS 请求（CORS 预检）和其他非 GET/POST 方法直接放行
        if request.method not in ("GET", "POST"):
            return await call_next(request)

        # 2. 检查是否跳过认证
        if request.url.path in self.skip_paths or any(request.url.path.startswith(p) for p in self.skip_paths):
            return await call_next(request)

        # 3. 提取 Token（优先从 Header，其次从 Query）
        access_token = request.headers.get("Lianjia-Access-Token")
        if not access_token:
            # 如果是环境是test或者dev,可以直接使用X-Nrs-User-Id
            if env_type == "test" or env_type == "dev":
                nrsUserId = request.headers.get("X-Nrs-User-Id")
                if not nrsUserId:
                    logger.info(f"请求路径 {request.url.path} 没有Lianjia-Access-Token")
                    return JSONResponse(status_code=401, content={"code": 401, "message": "Lianjia-Access-Token或者X-Nrs-User-Id为空", "data": None})
                else:
                    return await call_next(request)
            else:
                return JSONResponse(status_code=401, content={"code": 401, "message": "Lianjia-Access-Token为空", "data": None})

        # 4. 验证 Token 并获取 ucid
        ucid = await session_client.verify_token(access_token)
        if not ucid:
            return JSONResponse(status_code=401, content={"code": 401, "message": "无效的Token或Token已过期", "data": None})

        # 5. 将 ucid 注入到 Request Headers 中
        # 注意：需要使用 _headers 私有属性修改 Headers（Starlette 限制）
        request._headers = request.headers.mutablecopy()
        request._headers["X-Nrs-User-Id"] = str(ucid)
        request.scope["headers"] = [(k.encode(), v.encode()) for k, v in request._headers.items()]

        # 6. 继续处理请求
        return await call_next(request)

