class CacheManager:
    """缓存管理器(单例模式)"""

    _instance: "CacheManager | None" = None
    _strategy: CacheStrategy | None = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self):
        """初始化缓存管理器(只初始化一次)"""
        if self._strategy is None:
            self._initialize_strategy()

    def _initialize_strategy(self):
        """根据配置初始化缓存策略"""
        backend = dot_get(config, "cache.backend", "memory")

        if backend == "redis":
            prefix = dot_get(config, "cache.redis.prefix", "agent:cache:")
            self._strategy = RedisCache(prefix=prefix)
        else:
            max_size = dot_get(config, "cache.memory.max_size", 1000)
            self._strategy = MemoryCache(max_size=max_size)

    @property
    def strategy(self) -> CacheStrategy:
        """获取当前缓存策略"""
        if self._strategy is None:
            self._initialize_strategy()
        return self._strategy  # type: ignore

    async def get(self, key: str) -> Any | None:
        """获取缓存值"""
        return await self.strategy.get(key)

    async def set(self, key: str, value: Any, ttl: int | None = None) -> bool:
        """设置缓存值"""
        return await self.strategy.set(key, value, ttl)

    async def delete(self, key: str) -> bool:
        """删除缓存"""
        return await self.strategy.delete(key)

    async def clear(self) -> bool:
        """清空所有缓存"""
        return await self.strategy.clear()

    async def exists(self, key: str) -> bool:
        """判断缓存键是否存在"""
        return await self.strategy.exists(key)

